css:
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600;700&family=Montserrat:wght@400;500;600;700;800;900&family=Inter:wght@400;500;600&display=swap');
:root{--bg:#0D0D0D; --panel:#141210; --panel2:#17140f;
  --gold:#D4AF37; --gold-b:#F3DE8E; --gold-d:#A8842A;
  --ink:#FBF7EE; --body:#D9D3C6; --muted:#8F8A7D; --line:rgba(212,175,55,.30);
  --serif:'Cormorant Garamond',Georgia,serif;
  --disp:'Montserrat','Segoe UI',sans-serif;
  --text:'Inter','Segoe UI',sans-serif;}
.ebook, .ebook *{box-sizing:border-box}
.ebook,.ebook{margin:0;padding:0;background:#050505;color:var(--body);font-family:var(--text);-webkit-font-smoothing:antialiased}
.ebook .book{display:flex;flex-direction:column;align-items:center;gap:26px;padding:34px 14px 60px}
.ebook .page{position:relative;width:794px;height:1123px;background:var(--bg);
  overflow:hidden;box-shadow:0 30px 80px rgba(0,0,0,.65);
  border:1px solid rgba(212,175,55,.10);
  padding:52px 60px;display:flex;flex-direction:column;}
.ebook .page::before{content:"";position:absolute;inset:0;pointer-events:none;
  background:
   radial-gradient(120% 60% at 50% -8%, rgba(212,175,55,.10), transparent 60%),
   radial-gradient(90% 50% at 110% 108%, rgba(212,175,55,.06), transparent 60%);}
.ebook .mi{width:1em;height:1em;display:block}
.ebook .box-ic{color:var(--gold);display:inline-flex;width:18px;height:18px}
.ebook .box-ic .mi{width:18px;height:18px}
.ebook /* ---- header / footer ---- */
.phead{display:flex;justify-content:space-between;align-items:center;position:relative;z-index:2}
.ebook .brand{display:flex;align-items:center;gap:10px}
.ebook .mark{width:26px;height:26px;border-radius:5px;object-fit:cover;border:1px solid var(--line)}
.ebook .wm{font-family:var(--disp);font-weight:800;font-size:12px;letter-spacing:3px;color:var(--ink)}
.ebook .eyebrow{font-family:var(--disp);font-weight:600;font-size:9.5px;letter-spacing:3.5px;color:var(--gold)}
.ebook .hrule{height:1px;background:linear-gradient(90deg,var(--gold),rgba(212,175,55,.05));margin:14px 0 0;position:relative;z-index:2}
.ebook .pbody{flex:1;display:flex;flex-direction:column;position:relative;z-index:2;padding-top:22px}
.ebook .pfoot{display:flex;justify-content:space-between;align-items:center;border-top:1px solid rgba(212,175,55,.14);padding-top:12px;margin-top:8px;position:relative;z-index:2}
.ebook .foot-b{font-family:var(--disp);font-size:8.5px;letter-spacing:2.6px;color:var(--muted);font-weight:600}
.ebook .foot-n{font-family:var(--disp);font-size:9px;letter-spacing:2px;color:var(--gold);font-weight:700}
.ebook .l-eyebrow{font-family:var(--disp);font-weight:700;font-size:10px;letter-spacing:4px;color:var(--gold);display:block;margin-bottom:6px}
.ebook .l-eyebrow.center{text-align:center}
.ebook /* ---- lesson head ---- */
.lhead{display:flex;align-items:flex-start;gap:20px;margin-bottom:20px}
.ebook .lnum{font-family:var(--serif);font-weight:700;font-size:82px;line-height:.8;
  color:transparent;-webkit-text-stroke:1.4px var(--gold);
  background:linear-gradient(180deg,rgba(212,175,55,.18),rgba(212,175,55,0));-webkit-background-clip:text;background-clip:text;}
.ebook .ltitle h1{font-family:var(--disp);font-weight:800;font-size:31px;line-height:1.05;color:var(--ink);margin:2px 0 0;letter-spacing:-.3px}
.ebook .lhead.solo .ltitle h1{font-size:28px;max-width:600px}
.ebook /* ---- lesson grid ---- */
.lgrid{display:grid;grid-template-columns:1.28fr .92fr;gap:24px;align-items:start;margin-bottom:16px}
.ebook .explain p{font-size:13.2px;line-height:1.68;color:var(--body);margin:0 0 9px}
.ebook .explain b{color:var(--ink);font-weight:600}
.ebook .lvis{background:linear-gradient(160deg,var(--panel),#0e0c09);border:1px solid var(--line);border-radius:14px;padding:10px;display:flex;align-items:center;justify-content:center;min-height:210px}
.ebook .illo{width:100%;height:auto;display:block}
.ebook /* ---- example ---- */
.example{border:1px solid var(--line);border-radius:12px;background:linear-gradient(180deg,rgba(212,175,55,.05),rgba(212,175,55,0));padding:13px 15px;margin-top:4px}
.ebook .ex-tag{display:flex;align-items:center;gap:8px;font-family:var(--disp);font-weight:700;font-size:10px;letter-spacing:2px;color:var(--gold);text-transform:uppercase;margin-bottom:6px}
.ebook .example p{margin:0;font-size:12.6px;line-height:1.6;color:var(--body)}
.ebook .example b{color:var(--gold-b);font-weight:700}
.ebook /* ---- boxes ---- */
.boxrow{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:2px 0 12px}
.ebook .box{border-radius:12px;padding:13px 15px}
.ebook .box-h{display:flex;align-items:center;gap:8px;font-family:var(--disp);font-weight:700;font-size:10.5px;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:6px}
.ebook .box p{margin:0;font-size:11.8px;line-height:1.55;color:var(--body)}
.ebook .box b{color:var(--ink)}
.ebook .box.tip{background:rgba(212,175,55,.07);border:1px solid var(--line)}
.ebook .box.tip .box-h{color:var(--gold)}
.ebook .box.warn{background:rgba(194,91,91,.07);border:1px solid rgba(194,91,91,.32)}
.ebook .box.warn .box-h{color:#e08a8a}
.ebook .box.warn .box-ic{color:#e08a8a}
.ebook .box.summ{background:linear-gradient(180deg,#141210,#100e0b);border:1px solid var(--line);border-left:3px solid var(--gold);margin-bottom:14px}
.ebook .box.summ .box-h{color:var(--gold)}
.ebook .box.summ p{color:var(--ink);font-weight:500}
.ebook /* ---- transition ---- */
.transition{margin-top:auto;display:flex;align-items:center;gap:10px;font-family:var(--serif);font-style:italic;font-size:15px;color:var(--gold-b);border-top:1px dashed rgba(212,175,55,.3);padding-top:12px}
.ebook .transition .box-ic{color:var(--gold)}
.ebook .transition b{font-style:normal;font-weight:600;color:var(--gold)}
.ebook /* ================= COVER ================= */
.cover{align-items:center;justify-content:center;text-align:center;padding:0}
.ebook .cover-glow{position:absolute;inset:0;background:
  radial-gradient(60% 42% at 50% 30%, rgba(212,175,55,.18), transparent 62%),
  radial-gradient(50% 30% at 50% 100%, rgba(212,175,55,.10), transparent 60%);}
.ebook .cover-inner{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;padding:60px 64px;width:100%}
.ebook .cover-eyebrow{font-family:var(--disp);font-weight:700;font-size:11px;letter-spacing:5px;color:var(--gold);margin-bottom:26px}
.ebook .cover-logo img{width:300px;height:300px;object-fit:cover;border-radius:16px;border:1px solid var(--line);box-shadow:0 20px 60px rgba(212,175,55,.14)}
.ebook .cover-line{width:120px;height:1px;background:linear-gradient(90deg,transparent,var(--gold),transparent);margin:26px 0}
.ebook .cover-title{font-family:var(--disp);font-weight:900;font-size:52px;line-height:1;letter-spacing:-1px;color:var(--ink);margin:0}
.ebook .cover-title span{background:linear-gradient(180deg,var(--gold-b),var(--gold) 55%,var(--gold-d));-webkit-background-clip:text;background-clip:text;color:transparent}
.ebook .cover-sub{font-family:var(--text);font-size:14px;line-height:1.7;color:var(--body);margin:20px 0 0;max-width:440px}
.ebook .cover-values{font-family:var(--disp);font-weight:700;font-size:12px;letter-spacing:4px;color:var(--gold)}
.ebook .cover-edition{font-family:var(--disp);font-weight:600;font-size:9.5px;letter-spacing:3.5px;color:var(--muted);margin-top:16px}
.ebook /* ================= WELCOME ================= */
.w-hero{margin-bottom:14px}
.ebook .w-title h1{font-family:var(--disp);font-weight:900;font-size:40px;line-height:1;color:var(--ink);margin:0;letter-spacing:-.5px}
.ebook .w-lead{font-size:14px;line-height:1.7;color:var(--body);margin:6px 0 20px;max-width:640px}
.ebook .w-lead b{color:var(--ink);font-weight:600}
.ebook .w-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:20px}
.ebook .wc{background:linear-gradient(170deg,var(--panel),#0e0c09);border:1px solid var(--line);border-radius:13px;padding:16px 15px}
.ebook .wc .box-ic{width:24px;height:24px;margin-bottom:10px}
.ebook .wc .box-ic .mi{width:24px;height:24px}
.ebook .wc h3{font-family:var(--disp);font-weight:700;font-size:13.5px;color:var(--ink);margin:0 0 6px}
.ebook .wc p{font-size:11.6px;line-height:1.55;color:var(--body);margin:0}
.ebook .wc b{color:var(--gold-b)}
.ebook .w-learn{border:1px solid var(--line);border-radius:13px;padding:16px 18px;background:rgba(212,175,55,.035);margin-bottom:18px}
.ebook .w-learn-h{font-family:var(--disp);font-weight:700;font-size:12px;letter-spacing:1px;color:var(--gold);margin-bottom:10px;text-transform:uppercase}
.ebook .checklist{list-style:none;margin:0;padding:0}
.ebook .checklist li{display:flex;align-items:flex-start;gap:10px;font-size:13px;line-height:1.5;color:var(--body);padding:5px 0}
.ebook .checklist.tight li{padding:4px 0;font-size:12.6px}
.ebook .ck{color:var(--gold);width:17px;height:17px;flex:0 0 17px;margin-top:1px}
.ebook .ck .mi{width:17px;height:17px}
.ebook /* ================= ERRORS ================= */
.err-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px 22px;margin:6px 0 16px}
.ebook .err{display:flex;gap:12px;align-items:flex-start;border-bottom:1px solid rgba(212,175,55,.12);padding-bottom:10px}
.ebook .err-n{font-family:var(--serif);font-weight:700;font-size:26px;color:var(--gold);line-height:1;min-width:34px}
.ebook .err-t h3{font-family:var(--disp);font-weight:700;font-size:13.5px;color:var(--ink);margin:0 0 3px}
.ebook .err-t p{font-size:11.3px;line-height:1.45;color:var(--muted);margin:0}
.ebook /* ================= CHECKLIST PAGE ================= */
.chk-lead{font-size:13px;line-height:1.65;color:var(--body);margin:2px 0 16px;max-width:640px}
.ebook .chk-lead b{color:var(--ink)}
.ebook .checklist.big li{font-size:13.6px;padding:9px 0;border-bottom:1px solid rgba(212,175,55,.1);color:var(--body)}
.ebook .ckbox{width:19px;height:19px;flex:0 0 19px;border:1.6px solid var(--gold);border-radius:5px;margin-top:1px;background:rgba(212,175,55,.06)}
.ebook /* ================= FINAL ================= */
.final{display:flex;flex-direction:column;align-items:center;text-align:center;flex:1}
.ebook .final-badge img{width:88px;height:88px;object-fit:cover;border-radius:14px;border:1px solid var(--line);box-shadow:0 14px 40px rgba(212,175,55,.16);margin-bottom:14px}
.ebook .final-title{font-family:var(--disp);font-weight:900;font-size:34px;line-height:1.06;color:var(--ink);margin:6px 0 0;letter-spacing:-.4px}
.ebook .final-title span{background:linear-gradient(180deg,var(--gold-b),var(--gold),var(--gold-d));-webkit-background-clip:text;background-clip:text;color:transparent}
.ebook .final-lead{font-size:13px;line-height:1.65;color:var(--body);max-width:520px;margin:14px 0 22px}
.ebook .final-lead b{color:var(--ink)}
.ebook .steps{display:flex;flex-direction:column;gap:12px;width:100%;max-width:560px;margin-bottom:22px}
.ebook .step{display:flex;gap:14px;align-items:center;text-align:left;background:linear-gradient(170deg,var(--panel),#0e0c09);border:1px solid var(--line);border-radius:12px;padding:13px 16px}
.ebook .step-n{font-family:var(--disp);font-weight:800;font-size:18px;color:#0D0D0D;background:linear-gradient(180deg,var(--gold-b),var(--gold-d));width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex:0 0 34px}
.ebook .step h3{font-family:var(--disp);font-weight:700;font-size:14px;color:var(--ink);margin:0 0 2px}
.ebook .step p{font-size:11.6px;line-height:1.45;color:var(--body);margin:0}
.ebook .cta{width:100%;max-width:560px;border:1px solid var(--gold);border-radius:16px;padding:22px;background:radial-gradient(120% 120% at 50% 0%,rgba(212,175,55,.14),rgba(212,175,55,.03));margin-bottom:20px}
.ebook .cta-k{font-family:var(--disp);font-weight:700;font-size:10px;letter-spacing:4px;color:var(--gold);margin-bottom:8px}
.ebook .cta-main{font-family:var(--disp);font-weight:800;font-size:22px;color:var(--ink)}
.ebook .cta-main .hash{background:linear-gradient(180deg,var(--gold-b),var(--gold-d));-webkit-background-clip:text;background-clip:text;color:transparent}
.ebook .cta-sub{font-size:12px;color:var(--body);margin-top:8px}
.ebook .final-quote{font-family:var(--serif);font-style:italic;font-size:20px;color:var(--gold-b);margin-top:auto}
.ebook .final-brand{font-family:var(--disp);font-weight:700;font-size:9px;letter-spacing:3px;color:var(--muted);margin-top:10px}
.ebook /* ================= PRINT ================= */
@page{size:A4;margin:0}
@media print{html,body{background:#fff}
.ebook .book{gap:0;padding:0}
.ebook .page{box-shadow:none;border:none;width:210mm;height:297mm;padding:14mm 16mm;page-break-after:always;break-after:page}
.ebook .page:last-child{page-break-after:auto}
.ebook .page::before,.ebook .cover-glow{-webkit-print-color-adjust:exact;print-color-adjust:exact}
.ebook, .ebook *{-webkit-print-color-adjust:exact;print-color-adjust:exact}
